import{_ as l,c as t,o as r,ag as e}from"./chunks/framework.Bkod66qp.js";const b=JSON.parse('{"title":"공연장 사용규정","description":"","frontmatter":{"title":"공연장 사용규정","subtitle":"","doc_id":"","last_update":"2022-07-01","author":"","categories":[],"tags":[]},"headers":[],"relativePath":"regulation/801_공연장 사용규정(220701).md","filePath":"regulation/801_공연장 사용규정(220701).md"}'),i={name:"regulation/801_공연장 사용규정(220701).md"};function o(s,a,n,c,d,h){return r(),t("div",null,a[0]||(a[0]=[e(`<h1 id="law-title" class="center" tabindex="-1">공연장 사용규정 <a class="header-anchor" href="#law-title" aria-label="Permalink to &quot;공연장 사용규정 {#law-title .center}&quot;">​</a></h1><div style="text-align:right;"><pre style="display:inline-block;margin:0;white-space:pre;font-family:monospace;">제정 2004.  12.  22
개정 2007.   9.  21
개정 2008.   6.  30
개정 2008.   8.  29
개정 2010.   3.  30
개정 2018.   3.  23
개정 2022.   7.   1</pre></div><h2 id="article1" class="sr-only" tabindex="-1">제1조 (목적 및 기능) <a class="header-anchor" href="#article1" aria-label="Permalink to &quot;제1조 (목적 및 기능) {#article1 .sr-only}&quot;">​</a></h2><p><strong>제1조(목적 및 기능)</strong> ① 이 규정은 재단법인 서울문화재단(이하 “재단” 이라 한다) 에서 운영하는 공연장의 대관 및 사용에 관하여 필요한 사항을 규정함을 목적으로 한다.<br> ② 공연장은 공정하고 안전한 창작생태계 조성 및 창작과 향유가 선순환되는 예술생태계 조성을 선도하여 서울의 문화예술 진흥에 기여한다. &lt;신설 2022. 7. 1.&gt;</p><h2 id="article2" class="sr-only" tabindex="-1">제2조 (용어의 정의) <a class="header-anchor" href="#article2" aria-label="Permalink to &quot;제2조 (용어의 정의) {#article2 .sr-only}&quot;">​</a></h2><p><strong>제2조(용어의 정의)</strong> ① “대관” 및 “사용”이라 함은 공연, 연습, 녹음, 녹화 등을 위하여 시설, 설비 및 부수장비를 소정의 절차를 거쳐 사용하는 것과 관련 부수행위를 위하여 공연장의 시설 설비를 사용하는 것을 말한다.<br> ② “사용자”라 함은 이 규정을 인정하고 재단의 사용승인을 받아 재단과 계약을 체결한 사람을 말한다.<br> ③ 삭제 &lt;2022. 7. 1.&gt;<br> ④ “사용료”란 본 규정 및 공연장 사용 내규(이하 ‘내규’라 한다)에 따라 계약 체결 시 정하는 공연장 및 기타 부속 공간에 대한 대관료를 말한다. &lt;신설 2022. 7. 1.&gt;<br> ⑤ “부가사용료”란 계약 체결 시 발생하는 대관료 외 계약 체결 이후 공연 종료 시까지 발생하는 추가 사용료, 부대시설 및 장비 사용료 등에 대한 사용료를 말한다. &lt;신설 2022. 7. 1.&gt;<br> ⑥ “공연자”란 공연 제작 및 실연하는 자로 출연자와 스태프를 포함한다. &lt;신설 2022. 7. 1.&gt;<br> ⑦ “무대 변경”이란 작품 특성에 따라 공연자 및 관객의 안전 등을 고려하여 가변형 공연장의 무대 및 객석의 형태를 변경하는 것을 말한다. &lt;신설 2022. 7. 1.&gt;</p><h2 id="article3" class="sr-only" tabindex="-1">제3조 (대관 및 사용범위) <a class="header-anchor" href="#article3" aria-label="Permalink to &quot;제3조 (대관 및 사용범위) {#article3 .sr-only}&quot;">​</a></h2><p><strong>제3조(대관 및 사용범위)</strong> 이 규정의 적용을 받는 사용시설 및 설비는 공연장에 관련된 다음 각 항의 공간, 부대시설 및 장비를 말하며 세부 내용은 내규로 정한다. &lt;개정 2022. 7. 1.&gt;<br> ① 대관 공간</p><ol><li>공연장</li><li>기타 부속 공간<br> ② 부대시설 및 장비</li></ol><h2 id="article4" class="sr-only" tabindex="-1">제4조 (대관의 종류 및 신청) <a class="header-anchor" href="#article4" aria-label="Permalink to &quot;제4조 (대관의 종류 및 신청) {#article4 .sr-only}&quot;">​</a></h2><p><strong>제4조(대관의 종류 및 신청)</strong> ① 제3조의 공간, 부대시설 및 장비를 대관 받고자 하는 자(이하 “사용자”라 한다)는 대관신청서를 재단에 제출하여야 한다. &lt;개정 2022. 7. 1.&gt;<br> ② 대관은 신청 시기에 따라 정기대관과 수시대관으로, 사용 목적에 따라 공연대관과 공연준비 대관, 철수대관 등으로 구분한다. &lt;개정 2022. 7. 1.&gt;<br> ③ 정기대관 및 수시대관의 시기 및 기간, 방법 등은 내규로 따로 정한다. &lt;개정 2022. 7. 1.&gt;</p><h2 id="article5" class="sr-only" tabindex="-1">제5조 (대관심의위원회) <a class="header-anchor" href="#article5" aria-label="Permalink to &quot;제5조 (대관심의위원회) {#article5 .sr-only}&quot;">​</a></h2><p><strong>제5조(대관심의위원회)</strong> ① 재단은 정기대관신청을 승인함에 있어 공정을 기하기 위하여 별도의 대관심의위원회(이하 “위원회”라 한다)를 구성하여 운영한다.<br> ② 수시대관의 경우는 자체수시대관심의에 의한다. 단, 신청경합인 수시대관은 제1항의 위원회를 구성하여 운영한다.&lt;개정 2022. 7. 1.&gt;<br> ③ 제1항 및 제2항의 위원회 구성 및 운영에 관한 사항은 내규로 따로 정한다.</p><h2 id="article6" class="sr-only" tabindex="-1">제6조 (대관승인) <a class="header-anchor" href="#article6" aria-label="Permalink to &quot;제6조 (대관승인) {#article6 .sr-only}&quot;">​</a></h2><p><strong>제6조(대관승인)</strong> ① 재단은 대관신청 접수마감 후 별도로 정한 기일 안에 이를 심사하고, 대관승인 가부결과를 통지하여야 한다.<br> ② 대관승인을 결정함에 있어서 필요하다고 인정할 때에는 조건을 부과하거나 신청인과 협의하여 대관 기간 및 일정을 조정할 수 있다.<br> ③ 대관승인을 받은 자는 재단이 지정하는 날까지 대관계약을 체결하여야 한다.</p><h2 id="article7" class="sr-only" tabindex="-1">제7조 (사용시간) <a class="header-anchor" href="#article7" aria-label="Permalink to &quot;제7조 (사용시간) {#article7 .sr-only}&quot;">​</a></h2><p><strong>제7조(사용시간)</strong> ① 공연장의 사용시설 등에 대한 사용시간은 오전, 오후, 야간으로 구분하고, 세부사항은 내규로 따로 정한다.<br> ② 제1항에서 규정한 사용기간 중 일부 시간만을 사용한 경우에도 전 시간을 사용한 것으로 본다.</p><h2 id="article8" class="sr-only" tabindex="-1">제8조 (사용료 등) <a class="header-anchor" href="#article8" aria-label="Permalink to &quot;제8조 (사용료 등) {#article8 .sr-only}&quot;">​</a></h2><p><strong>제8조(사용료 등)</strong> 사용시설에 대한 사용료, 계약, 납부 등에 관한 사항은 내규로 따로 정한다.</p><h2 id="article9" class="sr-only" tabindex="-1">제9조 (사용료 특례) <a class="header-anchor" href="#article9" aria-label="Permalink to &quot;제9조 (사용료 특례) {#article9 .sr-only}&quot;">​</a></h2><p><strong>제9조(사용료 특례)</strong> ① 재단은 공용 또는 공익상 특별한 사유가 있다고 인정된 때에는 사용료의 일부 또는 전부를 감면할 수 있다.<br> ② 재단과 공동 주최, 후원, 기획 사용하는 공연 또는 행사의 경우 별도 정하는 바에 의거 사용료를 면제 또는 감면해 줄 수 있다.</p><h2 id="article10" class="sr-only" tabindex="-1">제10조 (사용료 반환) <a class="header-anchor" href="#article10" aria-label="Permalink to &quot;제10조 (사용료 반환) {#article10 .sr-only}&quot;">​</a></h2><p><strong>제10조(사용료 반환)</strong> 사용자가 사용료를 납부한 후 각 호의 1에 해당하는 경우에는 납부한 사용료의 전부 또는 일부를 반환하여야 한다.</p><ol><li>재해 기타 불가항력의 사유 및 공연장 안전문제로 인하여 사용이 불가능하게 된 경우 : 납부한 사용료 중 사용하지 아니한 일수에 해당하는 사용료 &lt;개정 2007. 9. 21.&gt;</li><li>삭제 &lt;2022. 7. 1.&gt;</li><li>사용예정일 31일 이전에 계약해지를 서면으로 통보한 경우에는 납부한 계약금을 모두 반환하며 31일 미만일 경우는 내규로 따로 정한다. &lt;개정 2018. 3. 23., 2022. 7. 1.&gt;</li><li>부대시설 및 장비의 경우 사용일 이전에 서면으로 사용취소신청을 한 경우 : 부대시설 및 장비의 사용료 납부금액 전액 반환 &lt;신설 2008. 6. 30.&gt;, &lt;개정 2022. 7. 1.&gt;</li></ol><h2 id="article11" class="sr-only" tabindex="-1">제11조 (사용제한) <a class="header-anchor" href="#article11" aria-label="Permalink to &quot;제11조 (사용제한) {#article11 .sr-only}&quot;">​</a></h2><p><strong>제11조(사용제한)</strong> ① 다음 각 호의 1에 해당하는 경우에는 대관 및 사용승인을 하지 아니한다.</p><ol><li>법령을 위반하는 내용의 공연 또는 행사 &lt;개정 2022. 7. 1.&gt;</li><li>공연장의 시설 또는 설비를 훼손할 우려가 있는 공연 또는 행사 &lt;개정 2022. 7. 1.&gt;</li><li>정치적 또는 종교적 집회 등의 행사 &lt;개정 2022. 7. 1.&gt;</li><li>기타 공연장 시설 및 설비의 관리 유지상 부적절하거나 안전에 문제가 있다고 판단되는 공연 또는 행사 &lt;개정 2008. 8. 29., 2022. 7. 1.&gt;</li><li>아마추어 공연단체(단, 전업으로 예술활동을 하는 개인 및 예술학교의 경우에는 신청할 수 있음) &lt;신설 2007. 9. 21.&gt;, &lt;개정 2018. 3. 23.&gt;</li><li>본 규정을 위반하는 행위를 할 우려가 명백한 경우 &lt;신설 2007. 9. 21.&gt;<br> ② 다음 각 호의 1에 해당하는 경우에는 대관 및 사용승인을 철회, 변경 또는 그 사용을 제한, 정지시킬 수 있다. 이 경우 사용자에게 손해가 있더라도 적법한 절차에 따라 재단은 배상책임을 지지 않을 수 있다. &lt;개정 2022. 7. 1.&gt;</li><li>이 규정 또는 이 규정에 의한 내규나 지시에 위반한 때</li><li>재해 또는 공연장 안전문제 등 불가항력의 사유로 인하여 공연장의 사용이 불가능한 때 &lt;개정 2010. 3. 30.&gt;</li><li>사용목적을 위반하거나 사용료를 지정기일까지 납부하지 아니한 때</li><li>대관승인 후 신청기재 사실이 허위로 밝혀졌을 때 &lt;신설 2007. 9. 21.&gt;</li><li>이 규정 또는 이 규정에 의한 내규에서 정한 기일 내에 계약을 체결하지 않았을 때 &lt;신설 2006. 2. 21.&gt;</li><li>대관계약 후 임의로 공연물 자체를 변경하여 공연하는 경우 &lt;신설 2022. 7. 1.&gt;<br> ③ 대관 및 사용승인 후 다음 각 호의 1에 해당하는 행위를 한 자에 대해서 재단은 다음 대관 신청 시 대관을 허가하지 아니할 수 있다. &lt;개정 2022. 7. 1.&gt;</li><li>제1항의 제1호 내지 제3호에 해당하는 행위를 한 자</li><li>최근 2년 내에 3회 이상 이 규정이 정한 기일 내에 계약을 체결하지 않은 자</li><li>제2항 3호에 해당하는 행위를 한 자</li><li>제2항의 규정에 따라 대관 및 사용승인이 철회 또는 정지된 경우 &lt;신설 2007. 9. 21.&gt;</li><li>사용자가 대관사용권을 재단의 동의 없이 타인에게 양도 또는 전대한 경우 &lt;신설 2007. 9. 21.&gt;</li><li>사용자가 재단의 승인 없이 공연 내용을 임의로 변경하여 공연한 경우 &lt;신설 2007. 9. 21.&gt;</li></ol><h2 id="article12" class="sr-only" tabindex="-1">제12조 (재단과 사용자의 의무 및 책임) <a class="header-anchor" href="#article12" aria-label="Permalink to &quot;제12조 (재단과 사용자의 의무 및 책임) {#article12 .sr-only}&quot;">​</a></h2><p><strong>제12조(재단과 사용자의 의무 및 책임)</strong> ① 삭제 &lt;2022. 7. 1.&gt;<br> ② 삭제 &lt;2022. 7. 1.&gt;<br> ③ 삭제 &lt;2022. 7. 1.&gt;<br> ④ 삭제 &lt;2022. 7. 1.&gt;<br> ⑤ 재단과 사용자의 의무와 책임은 본 규정 및 내규, 대관계약서에 따른다. &lt;신설 2022. 7. 1.&gt;<br> ⑥ 재단은 규정 및 내규에 명시한 대관절차, 대관료 납부 및 환불정책, 공연장 이용 시설 등 사용자에게 필요한 중요정보를 공개한다. &lt;신설 2022. 7. 1.&gt;</p><h2 id="article13" class="sr-only" tabindex="-1">제13조 (사용자의 안전관리) <a class="header-anchor" href="#article13" aria-label="Permalink to &quot;제13조 (사용자의 안전관리) {#article13 .sr-only}&quot;">​</a></h2><p><strong>제13조(사용자의 안전관리)</strong> ① 사용자가 공연, 행사를 위하여 설치하는 무대장치나 시설물은 &quot;화재예방, 소방시설 설치ㆍ유지 및 안전관리에 관한 법률&quot; 제12조(소방대상물의 방염 등)에 의거 방염성능이 있는 것으로 하여야 한다. &lt;개정 2008. 8. 29., 2022. 7. 1.&gt;<br> ② 제1항의 방염성능이 있는 것으로 할 물품에 대하여는 행정안전부령으로 지정된 방염성능 검사를 받아 방염필증을 재단에 제출하여 승인을 득한 후 무대장치 반입이나 시설을 설치할 수 있다. &lt;개정 2022. 7. 1.&gt;<br> ③ 재단은 공연이나 행사시 화재발생 우려가 있는 물품 또는 설비의 사용을 제한할 수 있다. &lt;개정 2022. 7. 1.&gt;<br> ④ 사용자가 공연장에 시설되어 있지 않은 외부조명, 음향 등을 사용할 시 전기사업법 제45조 제1항에 의거 전기안전관리자의 선임 또는 전기안전관리대행업체의 안전점검에 합격하여야만 전기를 사용할 수 있다.<br> ⑤ 제4항의 안전점검은 재단의 전기안전관리자의 입회하에 실시하며, 이에 소요되는 제반비용은 사용자가 부담한다.<br> ⑥ 각 항의 규정을 위반한 자에 대하여 재단은 대관사용계약을 해지하거나 시설 사용을 제한할 수 있으며 이로 인한 손해배상이나 손실보상의 책임을 지지 아니하며 사용자는 적법한 지침에 따라야 한다. &lt;개정 2022. 7. 1.&gt;<br> ⑦ 재단은 「공연법」 제11조의 5에 따라 화재 등 재해나 위급상황 발생 시 관람자가 안전하게 피난할 수 있도록 피난 통로를 확보해야 하며, 안전 관리를 위해 다음 각 호를 준수하여야 한다. &lt;신설 2022. 7. 1.&gt;</p><ol><li>공연장으로 등록된 객석수를 초과하여 보조석 등을 운용할 수 없다.</li><li>단, 작품의 특성상 공연장 무대 형태를 변경하여 사용해야 할 경우, 재단이 정한 지침에 따라 사전승인을 얻어 결정한다.<br> ⑧ ｢공연법｣ 제11조의 4 및 ｢동법 시행령｣ 제9조의4 에 의해 공연에 참여하는 공연자는 법률이 정한 안전교육을 반드시 이수하여야 한다. &lt;신설 2022. 7. 1.&gt;</li></ol><h2 id="article14" class="sr-only" tabindex="-1">제14조 (사용자의 설비) <a class="header-anchor" href="#article14" aria-label="Permalink to &quot;제14조 (사용자의 설비) {#article14 .sr-only}&quot;">​</a></h2><p><strong>제14조(사용자의 설비)</strong> ① 사용자가 사용기간 중 특별한 장치와 설비를 하고자 할 때는 미리 재단의 승인을 받아 사용자 부담으로 시설물을 설치할 수 있다.<br> ② 제1항의 규정에 의하여 시설물을 설치하였을 때에는 사용기간 만료와 동시에 이를 철거하고 원상복구를 하여야 한다.<br> ③ 사용자가 제2항의 규정에 의한 의무를 이행하지 아니할 때에는 이를 재단에서 직접 원상복구하고 그 비용을 사용자로부터 징수한다. 만약 재단이 철거할 시 파손에 대한 책임을 지지 않는다.</p><h2 id="article15" class="sr-only" tabindex="-1">제15조 (사전협의 및 공연‧행사 진행 협조) <a class="header-anchor" href="#article15" aria-label="Permalink to &quot;제15조 (사전협의 및 공연‧행사 진행 협조) {#article15 .sr-only}&quot;">​</a></h2><p><strong>제15조(사전협의 및 공연‧행사 진행 협조)</strong> ① 사용자는 공연 및 행사의 원활한 진행을 위하여 최초 사용일 전에 재단에 진행계획서를 제출하고, 시설 설비 등의 변경을 요하는 경우 사용자와 설치제작자가 필히 참석, 설치 방안 등 제반사항을 재단과 협의하여야 한다. 재단은 시설 운영에 중대한 우려가 예상되는 경우 행사를 취소시킬 수 있다. &lt;개정 2022. 7. 1.&gt;<br> ② 무대작업 및 공연진행시에 사용자는 재단의 안전수칙을 준수해야 하며, 각종 장치 및 장비 설치는 기술 검토 후 재단 기술진의 감독 하에 작업함을 원칙으로 한다.<br> ③ 삭제 &lt;2022. 7. 1.&gt;<br> ④ 공연장 시설 사용 시 재단이 감당할 수 없는 인력소요가 발생할 경우 사용자의 부담으로 인력을 충원한다.<br> ⑤ 공연장 내 광고 홍보물 제작 및 부착, 방송 및 부대행사 진행, 객석 유형 및 좌석 수, 입장권의 발행 및 관리 등 기타 공연 및 행사 진행에 필요한 제반 사항은 내규로 따로 정한다. &lt;신설 2022. 7. 1.&gt;</p><h2 id="article16" class="sr-only" tabindex="-1">제16조 (광고 홍보물의 협의) <a class="header-anchor" href="#article16" aria-label="Permalink to &quot;제16조 (광고 홍보물의 협의) {#article16 .sr-only}&quot;">​</a></h2><p><strong>제16조(광고 홍보물의 협의)</strong> 삭제 &lt;2022. 7. 1.&gt;</p><h2 id="article17" class="sr-only" tabindex="-1">제17조 (방송 및 부대행사) <a class="header-anchor" href="#article17" aria-label="Permalink to &quot;제17조 (방송 및 부대행사) {#article17 .sr-only}&quot;">​</a></h2><p><strong>제17조(방송 및 부대행사)</strong> 삭제 &lt;2022. 7. 1.&gt;</p><h2 id="article18" class="sr-only" tabindex="-1">제18조 (객석수의 제한) <a class="header-anchor" href="#article18" aria-label="Permalink to &quot;제18조 (객석수의 제한) {#article18 .sr-only}&quot;">​</a></h2><p><strong>제18조(객석수의 제한)</strong> 삭제 &lt;2022. 7. 1.&gt;</p><h2 id="article19" class="sr-only" tabindex="-1">제19조 (입장권의 발행) <a class="header-anchor" href="#article19" aria-label="Permalink to &quot;제19조 (입장권의 발행) {#article19 .sr-only}&quot;">​</a></h2><p><strong>제19조(입장권의 발행)</strong> 삭제 &lt;2022. 7. 1.&gt;</p><h2 id="article20" class="sr-only" tabindex="-1">제20조 (입장제한) <a class="header-anchor" href="#article20" aria-label="Permalink to &quot;제20조 (입장제한) {#article20 .sr-only}&quot;">​</a></h2><p><strong>제20조(입장제한)</strong> 재단은 다음 각 호의 1에 해당하는 경우에는 사용자에게 관람자의 입장을 거절하거나 퇴장을 요구할 수 있다.</p><ol><li>전염병 질환이 있는 자</li><li>만취자 및 무단 출입자</li><li>타인에게 위험을 주거나 또는 방해가 될 물품을 휴대한 자</li><li>재단의 검인이 없는 입장권을 소지한 자</li><li>기타 재단이 안전 유지상 필요하다고 인정되는 자</li></ol><h2 id="article21" class="sr-only" tabindex="-1">제21조 (배상책임) <a class="header-anchor" href="#article21" aria-label="Permalink to &quot;제21조 (배상책임) {#article21 .sr-only}&quot;">​</a></h2><p><strong>제21조(배상책임)</strong> ① 재단은 제11조에 따라 사용을 제한하였을 때 이로 인한 손해배상이나 손실보상의 책임을 지지 않을 수 있다. &lt;개정 2022. 7. 1.&gt;<br> ② 사용자는 대관 사용에 있어서 계약서에 명시한 내용 및 기타 재단이 정하는 사항을 준수하여야 하며 시설 및 설비에 대하여 선량한 관리자로서의 주의의무를 다 하여야 한다.<br> ③ 사용과 관련하여 발생한 사고에 대해서는 사용자가 민, 형사상의 모든 책임을 진다. 다만, 재단의 지시를 이행하였거나 재단과 사전 협의한 후 무대장치 및 시설물 등을 설치하여 사고가 발생할 경우에는 재단과 사용자가 책임한계를 협의 결정한다.<br> ④ 삭제 &lt;2010. 3. 30.&gt;</p><h2 id="article22" class="sr-only" tabindex="-1">제22조 (적용규정) <a class="header-anchor" href="#article22" aria-label="Permalink to &quot;제22조 (적용규정) {#article22 .sr-only}&quot;">​</a></h2><p><strong>제22조(적용규정)</strong> 이 규정은 대관계약서 일부로서의 효력을 지니며 관련법령 및 이 규정에 명시되지 않은 사항은 재단과 사용자가 협의하여 정하는 바에 따른다. &lt;개정 2022. 7. 1.&gt;</p><h2 id="article23" class="sr-only" tabindex="-1">제23조 (시행내규) <a class="header-anchor" href="#article23" aria-label="Permalink to &quot;제23조 (시행내규) {#article23 .sr-only}&quot;">​</a></h2><p><strong>제23조(시행내규)</strong> 이 규정 시행에 관하여 필요한 사항은 내규로 따로 정한다.</p><h2 id="addendum1" class="sr-only" tabindex="-1">부칙 <a class="header-anchor" href="#addendum1" aria-label="Permalink to &quot;부칙 {#addendum1 .sr-only}&quot;">​</a></h2><p><strong>부칙</strong><br> 제1조(시행일) 이 규정은 이사회의 승인을 얻는 날로부터 시행한다.<br> 제2조(사용에 대한 경과조치) 이 규정 시행 전에 대표이사의 시행 승인을 받은 것은 이 규정에 의하여 사용 승인된 것으로 본다.</p><h2 id="addendum2" class="sr-only" tabindex="-1">부칙 <a class="header-anchor" href="#addendum2" aria-label="Permalink to &quot;부칙 {#addendum2 .sr-only}&quot;">​</a></h2><p><strong>부칙</strong> &lt;2007. 9. 21.&gt;<br> 이 규정은 2007년 9월 21일부터 시행한다.</p><h2 id="addendum3" class="sr-only" tabindex="-1">부칙 <a class="header-anchor" href="#addendum3" aria-label="Permalink to &quot;부칙 {#addendum3 .sr-only}&quot;">​</a></h2><p><strong>부칙</strong> &lt;2008. 6. 30.&gt;<br> 이 규정은 2008년 6월 30일부터 시행한다.</p><h2 id="addendum4" class="sr-only" tabindex="-1">부칙 <a class="header-anchor" href="#addendum4" aria-label="Permalink to &quot;부칙 {#addendum4 .sr-only}&quot;">​</a></h2><p><strong>부칙</strong> &lt;2008. 8. 29.&gt;<br> 이 규정은 2008년 8월 29일부터 시행한다.</p><h2 id="addendum5" class="sr-only" tabindex="-1">부칙 <a class="header-anchor" href="#addendum5" aria-label="Permalink to &quot;부칙 {#addendum5 .sr-only}&quot;">​</a></h2><p><strong>부칙</strong> &lt;2010. 3. 30.&gt;<br> 이 규정은 2010년 3월 30일부터 시행한다.</p><h2 id="addendum6" class="sr-only" tabindex="-1">부칙 <a class="header-anchor" href="#addendum6" aria-label="Permalink to &quot;부칙 {#addendum6 .sr-only}&quot;">​</a></h2><p><strong>부칙</strong> &lt;2018. 3. 23.&gt;<br> 이 규정은 2018년 3월 23일부터 시행한다.</p><h2 id="addendum7" class="sr-only" tabindex="-1">부칙 <a class="header-anchor" href="#addendum7" aria-label="Permalink to &quot;부칙 {#addendum7 .sr-only}&quot;">​</a></h2><p><strong>부칙</strong> &lt;2022. 7. 1.&gt;<br> 이 규정은 2022년 7월 1일부터 시행한다.</p>`,67)]))}const u=l(i,[["render",o]]);export{b as __pageData,u as default};
